def random_state_for_action(action,rng):
    for _ in range(200000):
        s={k:rng.choice(v) for k,v in STATE_SCHEMA.items()}
        if valid_state(s) and oracle_action(s)==action:return s
    raise RuntimeError(action)
def balanced_states(n,seed):
    if n%6:raise ValueError("n must be divisible by six")
    rng=random.Random(seed); rows=[]
    for a in ACTIONS:
        for _ in range(n//6):rows.append(random_state_for_action(a,rng))
    rng.shuffle(rows);return rows
def render_state(s,family,rng,shuffle=True):
    clauses=[rng.choice(PHRASES[family][f][s[f]]) for f in STATE_SCHEMA]
    if shuffle:rng.shuffle(clauses)
    return " ".join(clauses)
def make_dataset(n,seed,family):
    rng=random.Random(seed+101);return [{"id":f"{family}-{i:05d}","text":render_state(s,family,rng),"state":s,"action":oracle_action(s)} for i,s in enumerate(balanced_states(n,seed))]
def inject_validation_stress(rows,seed):
    rng=random.Random(seed); critical=["permission","risk","information","reversibility","execution_possible","completed"]
    for i in range(0,min(120,len(rows)),2):
        row=rows[i];f=rng.choice(critical);current=row["state"][f];old=rng.choice([v for v in STATE_SCHEMA[f] if v!=current]);a=rng.choice(PHRASES["validation"][f][old]).rstrip(".");b=rng.choice(PHRASES["validation"][f][current]).rstrip(".");row["text"]=f"Earlier, {a.lower()}. But now, {b.lower()}. "+row["text"]
def write_jsonl(path,rows):
    Path(path).parent.mkdir(parents=True,exist_ok=True);Path(path).write_text("".join(json.dumps(r,sort_keys=True)+"\n" for r in rows),encoding="utf-8")
